// stlw002-find-stalls (PRO-236)
// Reads last 500 rows of cc_heartbeat_log.jsonl and last 1000 rows of
// cc_completion_log.jsonl. Emits stall_alerts for workers with no heartbeat
// in 5 min and no completion marker. Dedup: one alert per worker+ticket per hour.
const fs = require('fs');
const HB_PATH = '/miru-data/cc_heartbeat_log.jsonl';
const CP_PATH = '/miru-data/cc_completion_log.jsonl';
const STALL_S = 300;
const DEDUP_MS = 3600 * 1000;
const MAX_HB = 500;
const MAX_CP = 1000;

function readTail(p, n) {
  if (!fs.existsSync(p)) return [];
  const lines = fs.readFileSync(p, 'utf8').split(/\r?\n/).filter(l => l.trim());
  return lines.slice(-n);
}

function parseRows(lines) {
  const out = [];
  for (const l of lines) { try { out.push(JSON.parse(l)); } catch (_e) {} }
  return out;
}

const hbRows = parseRows(readTail(HB_PATH, MAX_HB));
const cpRows = parseRows(readTail(CP_PATH, MAX_CP));

const latest = {};
for (const row of hbRows) {
  const wid = String(row.worker_id || '').trim();
  if (!wid) continue;
  if (!latest[wid] || String(row.ts || '') > String(latest[wid].ts || '')) latest[wid] = row;
}

const done = {};
for (const row of cpRows) {
  const tid = String(row.ticket_id || '').trim();
  if (tid && tid.toLowerCase() !== 'null') done[tid] = true;
}

const sd = $getWorkflowStaticData('global');
if (!sd.stall_alerted || typeof sd.stall_alerted !== 'object' || Array.isArray(sd.stall_alerted)) {
  sd.stall_alerted = {};
}

const nowMs = Date.now();
for (const k of Object.keys(sd.stall_alerted)) {
  const t = new Date(sd.stall_alerted[k]).getTime();
  if (isNaN(t) || nowMs - t > DEDUP_MS) delete sd.stall_alerted[k];
}

const nowSec = nowMs / 1000;
const alerts = [];

for (const [wid, row] of Object.entries(latest)) {
  const tsStr = String(row.ts || '').trim();
  const tid = String(row.ticket_id || '').trim() || null;
  const hbSec = tsStr ? new Date(tsStr).getTime() / 1000 : NaN;
  if (isNaN(hbSec)) continue;
  if (nowSec - hbSec <= STALL_S) continue;
  if (tid && done[tid]) continue;
  const key = wid + ':' + (tid || 'none');
  if (sd.stall_alerted[key]) continue;
  sd.stall_alerted[key] = new Date().toISOString();
  alerts.push({
    worker_id: wid,
    ticket_id: tid,
    step: String(row.step || '').trim() || null,
    last_heartbeat_ts: tsStr,
    age_minutes: Math.round((nowSec - hbSec) / 60),
    branch: String(row.branch || '').trim() || null,
    stall_signal: String(row.stall_signal || '').trim() || null,
  });
}

return [{ json: { stall_alerts: alerts, checked_workers: Object.keys(latest).length } }];

// stlw004-build-message (PRO-236)
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
const a = $input.item.json.stall_alerts;
const lines = [
  '\uD83D\uDEA8 <b>Worker stall detected</b>',
  'Worker: ' + esc(a.worker_id || 'unknown'),
  'Ticket: ' + esc(a.ticket_id || 'none'),
  'Last step: ' + esc(a.step || 'unknown'),
  'Last heartbeat: ' + esc(a.last_heartbeat_ts || 'unknown') + ' (' + (a.age_minutes != null ? a.age_minutes : '?') + ' min ago)',
  'Branch: ' + esc(a.branch || 'none'),
  'Stall signal: ' + esc(a.stall_signal || 'none'),
];
return { json: { telegram_body: { chat_id: $env.TELEGRAM_CHAT_ID, text: lines.join('\n'), parse_mode: 'HTML', disable_notification: false } } };
